INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5752575, 835705, 109614, '<td valign="top">Nice setup and shot!</td>', 'Nice setup and shot!', '2009-12-03 15:47:05.000000', NULL, 1),
(5752582, 837116, 109614, '<td valign="top">Nice shot!</td>', 'Nice shot!', '2009-12-03 15:49:58.000000', NULL, 1),
(5752771, 837030, 110041, '<td valign="top">Awesome lighting. Very professional looking shot. I''d buy one.</td>', 'Awesome lighting. Very professional looking shot. I''d buy one.', '2009-12-03 18:09:08.000000', NULL, 1),
(5752772, 836917, 110041, '<td valign="top">Love it.</td>', 'Love it.', '2009-12-03 18:09:40.000000', NULL, 1),
(5752773, 836345, 110041, '<td valign="top">Awesome idea. The models are great. Just lacking in the execution.</td>', 'Awesome idea. The models are great. Just lacking in the execution.', '2009-12-03 18:10:00.000000', NULL, 1),
(5752882, 837126, 111808, '<td valign="top">The mirror on this is nice. To me, it symbolises both the playing of and the receiving of the Music, where what resonates out is reflected back again to be a greater whole. The diagonal placement of the bow adds a sense of movement and the rosin is zen. Kudos, well done.</td>', 'The mirror on this is nice. To me, it symbolises both the playing of and the receiving of the Music, where what resonates out is reflected back again to be a greater whole. The diagonal placement of the bow adds a sense of movement and the rosin is zen. Kudos, well done.', '2009-12-03 19:54:42.000000', NULL, 1),
(5752884, 836754, 43594, '<td valign="top">Nice composition and lightning, well done!</td>', 'Nice composition and lightning, well done!', '2009-12-03 19:55:10.000000', NULL, 1),
(5752919, 836973, 111808, '<td valign="top">The coloured pin heads on these really pop out against the black background and together they are very cheerful, almost like mini christmas ornaments. In the pin cushion, my eye kept going to the empty left side hole, but I do very much like this composition.</td>', 'The coloured pin heads on these really pop out against the black background and together they are very cheerful, almost like mini christmas ornaments. In the pin cushion, my eye kept going to the empty left side hole, but I do very much like this composition.', '2009-12-03 20:08:38.000000', NULL, 1),
(5752955, 837073, 48926, '<td valign="top">Love the shoes, don''t love the grain</td>', 'Love the shoes, don''t love the grain', '2009-12-03 20:20:50.000000', NULL, 1),
(5753053, 835841, 111534, '<td valign="top">knife is too dark but I like the idea.</td>', 'knife is too dark but I like the idea.', '2009-12-03 20:55:40.000000', NULL, 1),
(5753057, 835938, 111534, '<td valign="top">background is a little void, but nice lighting</td>', 'background is a little void, but nice lighting', '2009-12-03 20:57:03.000000', NULL, 1),
(5753065, 837030, 111534, '<td valign="top">an R/C fan perhaps...:)</td>', 'an R/C fan perhaps...:)', '2009-12-03 20:59:55.000000', NULL, 1),
(5753068, 836134, 111534, '<td valign="top">too confusing</td>', 'too confusing', '2009-12-03 21:00:45.000000', NULL, 1),
(5753179, 837126, 111534, '<td valign="top">reflection is too strong</td>', 'reflection is too strong', '2009-12-03 21:42:02.000000', NULL, 1),
(5753185, 835705, 111534, '<td valign="top">never knew there was so many tools..</td>', 'never knew there was so many tools..', '2009-12-03 21:44:03.000000', NULL, 1),
(5753191, 837000, 111534, '<td valign="top">very good I just wish the 3 on the left were in the light</td>', 'very good I just wish the 3 on the left were in the light', '2009-12-03 21:45:37.000000', NULL, 1),
(5753193, 836926, 111534, '<td valign="top">too bad they wouldn''t let you edit out the wires, nice execution</td>', 'too bad they wouldn''t let you edit out the wires, nice execution', '2009-12-03 21:46:28.000000', NULL, 1),
(5753291, 835961, 3735, '<td valign="top">wow I can''t stop looking at this  (10)</td>', 'wow I can''t stop looking at this  (10)', '2009-12-03 22:59:35.000000', NULL, 1),
(5753292, 836917, 88580, '<td valign="top">Just like a vintage appliance ad.  Well done.</td>', 'Just like a vintage appliance ad.  Well done.', '2009-12-03 23:00:50.000000', NULL, 1),
(5753299, 835705, 88580, '<td valign="top">Is there any time left to actually <i>play</i> it, though?  That really looks like way too much work.  I''ll stick to sax and a box of Ricos.  As far as the photo goes, I''m not a big fan of the lighting, and the environment looks a bit sterile.  The arrangement feels awkward and static.</td>', 'Is there any time left to actually play it, though?  That really looks like way too much work.  I''ll stick to sax and a box of Ricos.  As far as the photo goes, I''m not a big fan of the lighting, and the environment looks a bit sterile.  The arrangement feels awkward and static.', '2009-12-03 23:07:33.000000', NULL, 1),
(5753304, 836975, 88580, '<td valign="top">This has potential, but the uneven lighting is really bringing it down.  Also, is that tape holding down the tape?</td>', 'This has potential, but the uneven lighting is really bringing it down.  Also, is that tape holding down the tape?', '2009-12-03 23:10:31.000000', NULL, 1),
(5753497, 836657, 102024, '<td valign="top">The composition feels a bit off.  I think a little more balance could make this more compelling, perhaps.</td>', 'The composition feels a bit off.  I think a little more balance could make this more compelling, perhaps.', '2009-12-04 00:50:13.000000', NULL, 1),
(5753500, 836134, 102024, '<td valign="top">I think the reflection in the window kinda takes away from this</td>', 'I think the reflection in the window kinda takes away from this', '2009-12-04 00:50:46.000000', NULL, 1),
(5753511, 836937, 102024, '<td valign="top">The light seems a little too harsh.  I suppose it adds to that "summer feeling" but I think overall a softer light would be more beneficial to this image.</td>', 'The light seems a little too harsh.  I suppose it adds to that "summer feeling" but I think overall a softer light would be more beneficial to this image.', '2009-12-04 00:54:53.000000', NULL, 1),
(5753517, 835840, 102024, '<td valign="top">Lovely lighting</td>', 'Lovely lighting', '2009-12-04 00:58:28.000000', NULL, 1),
(5753518, 837050, 102024, '<td valign="top">Good use of the DOF</td>', 'Good use of the DOF', '2009-12-04 00:58:38.000000', NULL, 1),
(5753543, 835981, 28427, '<td valign="top">Ah...Le Creuset... I like the subtle reflection in the background.</td>', 'Ah...Le Creuset... I like the subtle reflection in the background.', '2009-12-04 02:01:02.000000', NULL, 1),
(5753548, 837033, 28427, '<td valign="top">how I hate those tools... But not your photograph</td>', 'how I hate those tools... But not your photograph', '2009-12-04 02:06:19.000000', NULL, 1),
(5753678, 836930, 110041, '<td valign="top">Looks like a very low resolution shot.<br/> <br/>Really underexposed on the cake.<br/> <br/>Awkward perspective - it''s not directly above and it makes the photo look flat.<br/> <br/>Awkward crop of the plate and cake.<br/> <br/>The idea has potential. I think the gooey filling of the cake would make for an excellent shot if taken from a lower angle and closer in. Some directed lighting would help.</td>', 'Looks like a very low resolution shot. Really underexposed on the cake. Awkward perspective - it''s not directly above and it makes the photo look flat. Awkward crop of the plate and cake. The idea has potential. I think the gooey filling of the cake would make for an excellent shot if taken from a lower angle and closer in. Some directed lighting would help.', '2009-12-04 06:33:00.000000', NULL, 1),
(5753679, 836969, 110041, '<td valign="top">Deadspace in the middle of the photo makes it unclear what I should be looking at.<br/>Out of focus needle and thread is distracting.<br/>Over saturation of reds is evident in the table making it blotchy.<br/>Lighting looks like it''s come from a the camera''s flash. Try using a torch to get more interesting lighting on the subjects.<br/> <br/>It does meet the challenge.</td>', 'Deadspace in the middle of the photo makes it unclear what I should be looking at.Out of focus needle and thread is distracting.Over saturation of reds is evident in the table making it blotchy.Lighting looks like it''s come from a the camera''s flash. Try using a torch to get more interesting lighting on the subjects. It does meet the challenge.', '2009-12-04 06:33:04.000000', NULL, 1),
(5753681, 837116, 105457, '<td valign="top">Great definition on this photo! Love the colours :)</td>', 'Great definition on this photo! Love the colours :)', '2009-12-04 06:33:36.000000', NULL, 1),
(5753683, 837045, 105457, '<td valign="top">I like the fact that you could piece together the title and the photo, because otherwise it would only be a photo of old knifes and forks :)</td>', 'I like the fact that you could piece together the title and the photo, because otherwise it would only be a photo of old knifes and forks :)', '2009-12-04 06:34:34.000000', NULL, 1),
(5753684, 836917, 105457, '<td valign="top">Very 70''s :)<br/>Love the details of the bow on top.</td>', 'Very 70''s :)Love the details of the bow on top.', '2009-12-04 06:35:04.000000', NULL, 1),
(5753687, 836178, 105457, '<td valign="top">Wow, you accomplished a lot of rules with this one. Great composition, contrast and setup. One of my favourites.</td>', 'Wow, you accomplished a lot of rules with this one. Great composition, contrast and setup. One of my favourites.', '2009-12-04 06:35:56.000000', NULL, 1),
(5753689, 836975, 105457, '<td valign="top">Great DOF, it''s just a shame that you can see the transparent tape in front. Anyway, lot of points from me.</td>', 'Great DOF, it''s just a shame that you can see the transparent tape in front. Anyway, lot of points from me.', '2009-12-04 06:36:51.000000', NULL, 1),
(5753690, 836590, 110041, '<td valign="top">Decent idea but the execution doesn''t match it.<br/> <br/>You''ve got lots of different elements (tools as it were) and I like the selective focus to try to emphasise just a couple of them.<br/> <br/>However the perspective is a little awkward.</td>', 'Decent idea but the execution doesn''t match it. You''ve got lots of different elements (tools as it were) and I like the selective focus to try to emphasise just a couple of them. However the perspective is a little awkward.', '2009-12-04 06:37:41.000000', NULL, 1),
(5753692, 836973, 105457, '<td valign="top">Looks like acupuncture :)good setup, a bit underexposed.</td>', 'Looks like acupuncture :)good setup, a bit underexposed.', '2009-12-04 06:38:07.000000', NULL, 1),
(5753695, 836976, 105457, '<td valign="top">Sorry, too shallow DOF, I would like to see a bit more brush, you have to look really hard to see the subject.</td>', 'Sorry, too shallow DOF, I would like to see a bit more brush, you have to look really hard to see the subject.', '2009-12-04 06:40:54.000000', NULL, 1),
(5753702, 836134, 105457, '<td valign="top">Good idea, but it''s pity because of the reflex.If you''re using a point and shoot, than there''s not much you can do, but if you''re using a reflex then you might consider in investing in a Polarizing filter, to cut the reflections.</td>', 'Good idea, but it''s pity because of the reflex.If you''re using a point and shoot, than there''s not much you can do, but if you''re using a reflex then you might consider in investing in a Polarizing filter, to cut the reflections.', '2009-12-04 06:47:20.000000', NULL, 1),
(5753703, 836969, 105457, '<td valign="top">A bit out of focus, and there''s a strange thing going on near the thread.</td>', 'A bit out of focus, and there''s a strange thing going on near the thread.', '2009-12-04 06:47:50.000000', NULL, 1),
(5753704, 837030, 105457, '<td valign="top">Great definition, and also great colours.</td>', 'Great definition, and also great colours.', '2009-12-04 06:48:35.000000', NULL, 1),
(5753705, 837027, 105457, '<td valign="top">Could have more contrast, but it''s a very good composition.</td>', 'Could have more contrast, but it''s a very good composition.', '2009-12-04 06:48:53.000000', NULL, 1),
(5753707, 836657, 105457, '<td valign="top">Damn, I guess you''ll get a lot of reactions from this one, but it''s very well done.<br/>Great seamless, good contrast and DOF. It could be closer, but it''s great nonetheless.</td>', 'Damn, I guess you''ll get a lot of reactions from this one, but it''s very well done.Great seamless, good contrast and DOF. It could be closer, but it''s great nonetheless.', '2009-12-04 06:50:03.000000', NULL, 1),
(5753708, 837122, 105457, '<td valign="top">It would be more obvious if you actually showed the piano keys, this way is a bit of a puzzle.</td>', 'It would be more obvious if you actually showed the piano keys, this way is a bit of a puzzle.', '2009-12-04 06:50:56.000000', NULL, 1),
(5753710, 836754, 105457, '<td valign="top">Excellent definition! I like the way that you didn''t freeze the metronome marker(?), so it''s actually dynamic. Good job also on the background.</td>', 'Excellent definition! I like the way that you didn''t freeze the metronome marker(?), so it''s actually dynamic. Good job also on the background.', '2009-12-04 06:53:14.000000', NULL, 1),
(5753711, 837050, 105457, '<td valign="top">Could use a bit more DOF, so that the needle is in total focus.</td>', 'Could use a bit more DOF, so that the needle is in total focus.', '2009-12-04 06:53:38.000000', NULL, 1),
(5753712, 837056, 105457, '<td valign="top">I like it. Don''t quite understand the potato, but :)<br/>Also, this photo would be great with selective colouring in the knife.</td>', 'I like it. Don''t quite understand the potato, but :)Also, this photo would be great with selective colouring in the knife.', '2009-12-04 06:55:40.000000', NULL, 1),
(5753715, 836620, 105457, '<td valign="top">Great self portrait. It''s cool that you''ve dressed the safety vest :-D</td>', 'Great self portrait. It''s cool that you''ve dressed the safety vest :-D', '2009-12-04 06:57:23.000000', NULL, 1),
(5753723, 835841, 105457, '<td valign="top">Great composition, I like the fact that it''s so uniquely lighted, very controlled.<br/>Good negative space on top, allowing the photo to breathe.<br/> <br/>Parabéns :)</td>', 'Great composition, I like the fact that it''s so uniquely lighted, very controlled.Good negative space on top, allowing the photo to breathe. Parabéns :)', '2009-12-04 07:15:00.000000', NULL, 1),
(5753729, 837127, 105457, '<td valign="top">Great tilt and shift here, did you use a lensbaby? Or an actual T&amp;S lens?<br/> <br/>Great job, could be better if you increased the saturation a bit.</td>', 'Great tilt and shift here, did you use a lensbaby? Or an actual T&S lens? Great job, could be better if you increased the saturation a bit.', '2009-12-04 07:19:43.000000', NULL, 1),
(5753739, 835626, 5364, '<td valign="top">I like the tight crop and the composition appeals to me, but the lack of any clear area in focus has thrown me a bit.</td>', 'I like the tight crop and the composition appeals to me, but the lack of any clear area in focus has thrown me a bit.', '2009-12-04 07:40:14.000000', NULL, 1),
(5753740, 835868, 5364, '<td valign="top">An excellent image. I like the diagonal lines and the way you have cropped this.</td>', 'An excellent image. I like the diagonal lines and the way you have cropped this.', '2009-12-04 07:41:30.000000', NULL, 1),
(5753744, 835841, 5364, '<td valign="top">I like this. The composition is good any my only complaint is that the cleaver has become part of the background, where I feel it would have been better being a little more distinct.</td>', 'I like this. The composition is good any my only complaint is that the cleaver has become part of the background, where I feel it would have been better being a little more distinct.', '2009-12-04 07:47:23.000000', NULL, 1),
(5753745, 837032, 5364, '<td valign="top">Good image. I like how you have chosen not to crop out the lights round the edges - it makes it much clearer that this is on stage.</td>', 'Good image. I like how you have chosen not to crop out the lights round the edges - it makes it much clearer that this is on stage.', '2009-12-04 07:49:03.000000', NULL, 1),
(5753747, 836590, 5364, '<td valign="top">Nicely lit and an interesting take on the challenge. The composition doesn''t quite work for me - the ruler(?) and blue thing aren''t adding anything relevant to the subject.</td>', 'Nicely lit and an interesting take on the challenge. The composition doesn''t quite work for me - the ruler(?) and blue thing aren''t adding anything relevant to the subject.', '2009-12-04 07:53:13.000000', NULL, 1),
(5753749, 836620, 5364, '<td valign="top">An excellent image, but almost immediately my eye was drawn to the watch which is a bit of a distraction. Very good otherwise.</td>', 'An excellent image, but almost immediately my eye was drawn to the watch which is a bit of a distraction. Very good otherwise.', '2009-12-04 07:55:35.000000', NULL, 1),
(5753750, 837110, 5364, '<td valign="top">This is an image I like. I think it''s the drama that appeals - capturing a moment in a dynamic process.</td>', 'This is an image I like. I think it''s the drama that appeals - capturing a moment in a dynamic process.', '2009-12-04 07:58:26.000000', NULL, 1),
(5753752, 837099, 5364, '<td valign="top">This is good and it only slightly annoys me that I can''t read the label.</td>', 'This is good and it only slightly annoys me that I can''t read the label.', '2009-12-04 07:59:44.000000', NULL, 1),
(5753827, 836657, 108580, '<td valign="top">Nice albeit gruesome shot, a bit OE and a bit too much negative space for a top mark</td>', 'Nice albeit gruesome shot, a bit OE and a bit too much negative space for a top mark', '2009-12-04 09:48:11.000000', NULL, 1),
(5753828, 836975, 108580, '<td valign="top">Nice shot and prop, front OOF tape detracts and draws my eye away, a bit too much negative space for a top mark</td>', 'Nice shot and prop, front OOF tape detracts and draws my eye away, a bit too much negative space for a top mark', '2009-12-04 09:48:15.000000', NULL, 1),
(5753831, 835938, 108580, '<td valign="top">Nice idea, good control of DOF on blade and shavings. Not fond of the BG colour and shadow blotch on the BG left above wood stump.</td>', 'Nice idea, good control of DOF on blade and shavings. Not fond of the BG colour and shadow blotch on the BG left above wood stump.', '2009-12-04 09:48:48.000000', NULL, 1),
(5753832, 837116, 108580, '<td valign="top">Nice crisp shot, would have liked to have seen a hand on the nozzle?</td>', 'Nice crisp shot, would have liked to have seen a hand on the nozzle?', '2009-12-04 09:48:53.000000', NULL, 1),
(5753834, 837127, 108580, '<td valign="top">Nice effect - Toy town, could have worked in the other challenge this week :)</td>', 'Nice effect - Toy town, could have worked in the other challenge this week :)', '2009-12-04 09:48:58.000000', NULL, 1),
(5753835, 836926, 108580, '<td valign="top">Great setup and idea. Hope the cleaver doesn''t top his tips :)<br/>Not fond of the background.</td>', 'Great setup and idea. Hope the cleaver doesn''t top his tips :)Not fond of the background.', '2009-12-04 09:49:02.000000', NULL, 1),
(5753836, 837020, 108580, '<td valign="top">Great idea and composure, flash lighting and shadows too harsh.</td>', 'Great idea and composure, flash lighting and shadows too harsh.', '2009-12-04 09:49:06.000000', NULL, 1),
(5753837, 837045, 108580, '<td valign="top">Quite a classic almost artsy shot. A little bit of extra saturation would have scored higher and less white visible @ bottom. Fill the whole frame with them tools :)</td>', 'Quite a classic almost artsy shot. A little bit of extra saturation would have scored higher and less white visible @ bottom. Fill the whole frame with them tools :)', '2009-12-04 09:49:11.000000', NULL, 1),
(5753839, 837148, 108580, '<td valign="top">Good lighting and DOF control. Meets challenge but would prefer less clutter and a tighter crop?</td>', 'Good lighting and DOF control. Meets challenge but would prefer less clutter and a tighter crop?', '2009-12-04 09:50:28.000000', NULL, 1),
(5753840, 837073, 108580, '<td valign="top">I like the grain!</td>', 'I like the grain!', '2009-12-04 09:50:32.000000', NULL, 1),
(5753843, 837121, 108580, '<td valign="top">Nice shot of a joinery and it''s tools. Pity the contrast is spread from blown top left to underexposed bottom right.</td>', 'Nice shot of a joinery and it''s tools. Pity the contrast is spread from blown top left to underexposed bottom right.', '2009-12-04 09:52:16.000000', NULL, 1),
(5753847, 835981, 108580, '<td valign="top">Crisp and clean, subtle lighting and almost pastel like colours. Nice.</td>', 'Crisp and clean, subtle lighting and almost pastel like colours. Nice.', '2009-12-04 09:55:14.000000', NULL, 1),
(5753849, 836936, 108580, '<td valign="top">Great fit with the title, but the DOF is off the horses and on the mountains. Focus manually or prefocus on the main subject.</td>', 'Great fit with the title, but the DOF is off the horses and on the mountains. Focus manually or prefocus on the main subject.', '2009-12-04 09:56:08.000000', NULL, 1),
(5753852, 836978, 108580, '<td valign="top">Nice close-up and great BW PP. The middle area separates main subject and top left bits too much.</td>', 'Nice close-up and great BW PP. The middle area separates main subject and top left bits too much.', '2009-12-04 09:57:22.000000', NULL, 1),
(5753853, 837081, 108580, '<td valign="top">Nice leading lines and colours.</td>', 'Nice leading lines and colours.', '2009-12-04 09:58:14.000000', NULL, 1),
(5753854, 835840, 108580, '<td valign="top">Ow! Interesting setup and exposure and them meets challenge. OOF and blur haters will mark you down on DPC.</td>', 'Ow! Interesting setup and exposure and them meets challenge. OOF and blur haters will mark you down on DPC.', '2009-12-04 09:59:32.000000', NULL, 1),
(5753857, 837032, 108580, '<td valign="top">A bit of a shoehorn imho thanks to the title. Quality of shot however is good as is the PP in BW. I would have cropped tighter however for more punch and the actor to stand out.</td>', 'A bit of a shoehorn imho thanks to the title. Quality of shot however is good as is the PP in BW. I would have cropped tighter however for more punch and the actor to stand out.', '2009-12-04 10:02:15.000000', NULL, 1),
(5753863, 837122, 108580, '<td valign="top">Hmmm, a bit of a shoehorn but I''m not marking it down. It has merit for the challenge in a wierd way. Expressions and actions are great as is the exposure.</td>', 'Hmmm, a bit of a shoehorn but I''m not marking it down. It has merit for the challenge in a wierd way. Expressions and actions are great as is the exposure.', '2009-12-04 10:03:59.000000', NULL, 1),
(5753865, 837030, 108580, '<td valign="top">Good exposure and nice tight crop and composition. Fits challenge.</td>', 'Good exposure and nice tight crop and composition. Fits challenge.', '2009-12-04 10:04:35.000000', NULL, 1),
(5753868, 837021, 99506, '<td valign="top">as opposed to vintage tools of the future? lol</td>', 'as opposed to vintage tools of the future? lol', '2009-12-04 10:05:57.000000', NULL, 1),
(5753869, 837110, 108580, '<td valign="top">Exciting photo but it''s lacking something. Light is good as is the fast s/s stopping the action. I know, it''s missing the welder and the mask.</td>', 'Exciting photo but it''s lacking something. Light is good as is the fast s/s stopping the action. I know, it''s missing the welder and the mask.', '2009-12-04 10:06:09.000000', NULL, 1),
(5753870, 837041, 108580, '<td valign="top">Great shot. Its a pair of scissors however hehe!</td>', 'Great shot. Its a pair of scissors however hehe!', '2009-12-04 10:06:14.000000', NULL, 1),
(5753871, 835969, 108580, '<td valign="top">Nice crisp clean, perhaps a pad underneath with handwriting might have given a bit more oomph.</td>', 'Nice crisp clean, perhaps a pad underneath with handwriting might have given a bit more oomph.', '2009-12-04 10:06:20.000000', NULL, 1),
(5753872, 836917, 108580, '<td valign="top">Very 70''s appliance and model but the tops and cupboards are 90''s!</td>', 'Very 70''s appliance and model but the tops and cupboards are 90''s!', '2009-12-04 10:06:24.000000', NULL, 1),
(5753873, 837050, 108580, '<td valign="top">Nice comp and crop, colours. I would have adjusted the needle to the same flat plane as the camera''s to get it all in focus as well as bit more ahead and behind. Would have given it a bit more punch.</td>', 'Nice comp and crop, colours. I would have adjusted the needle to the same flat plane as the camera''s to get it all in focus as well as bit more ahead and behind. Would have given it a bit more punch.', '2009-12-04 10:06:29.000000', NULL, 1),
