(5755085, 836978, 30454, '<td valign="top">Great details and DOF. One of my top score, good luck.</td>', 'Great details and DOF. One of my top score, good luck.', '2009-12-04 22:59:41.000000', NULL, 1),
(5755087, 835931, 30454, '<td valign="top">Great lighting, good composition. Good luck.</td>', 'Great lighting, good composition. Good luck.', '2009-12-04 23:00:15.000000', NULL, 1),
