(5755209, 836937, 108580, '<td valign="top">Bright, perhaps a bit too much so. Shadows are distracting.</td>', 'Bright, perhaps a bit too much so. Shadows are distracting.', '2009-12-05 01:02:24.000000', NULL, 1),
(5755246, 836104, 108580, '<td valign="top">Strange tools! Nice shot and setup, colours and location excellent. Clean shaven thug spoils it though :P They mostly have a hood covering their faces!</td>', 'Strange tools! Nice shot and setup, colours and location excellent. Clean shaven thug spoils it though :P They mostly have a hood covering their faces!', '2009-12-05 01:41:49.000000', NULL, 1),
(5755317, 837126, 5364, '<td valign="top">It''s a very good image, I''m just not keen on the background not being completely black, that you''ve cropped off the ends of the bow and I don''t see that this style of border is adding anything. However those are minor points.</td>', 'It''s a very good image, I''m just not keen on the background not being completely black, that you''ve cropped off the ends of the bow and I don''t see that this style of border is adding anything. However those are minor points.', '2009-12-05 02:41:21.000000', NULL, 1),
(5755321, 835961, 5364, '<td valign="top">Normally flash-lit photos like this look really bad, but you have processed this in a way that has minimised the flat look and made something much better.</td>', 'Normally flash-lit photos like this look really bad, but you have processed this in a way that has minimised the flat look and made something much better.', '2009-12-05 02:45:30.000000', NULL, 1),
(5755326, 835931, 5364, '<td valign="top">Excellently lit and well composed although I do find myself wanting to be able to read the title''s on the sheets of music.</td>', 'Excellently lit and well composed although I do find myself wanting to be able to read the title''s on the sheets of music.', '2009-12-05 02:48:27.000000', NULL, 1),
