(5755720, 836917, 112496, '<td valign="top">I find this EXTREMELY offensive!<br/> <br/>All she needs is some fishnets and high heels and youve done a great job of sitting the whole woman''s movement back 30 yrs. You pulled it off with the hairdo and pearls though. Unfortunately.</td>', 'I find this EXTREMELY offensive! All she needs is some fishnets and high heels and youve done a great job of sitting the whole woman''s movement back 30 yrs. You pulled it off with the hairdo and pearls though. Unfortunately.', '2009-12-05 12:03:11.000000', NULL, 1),
(5755725, 837073, 112496, '<td valign="top">Too grainy. Poor focus and crop.</td>', 'Too grainy. Poor focus and crop.', '2009-12-05 12:04:31.000000', NULL, 1),
(5755733, 836936, 112496, '<td valign="top">Doesnt meet contest criteria but great shot.</td>', 'Doesnt meet contest criteria but great shot.', '2009-12-05 12:06:46.000000', NULL, 1),
