(5755741, 836134, 112496, '<td valign="top">See very few tool but a lot of junk. Not fitting with contest criteria. I can make out only ONE tool (the drill). Rest is junk and parts.</td>', 'See very few tool but a lot of junk. Not fitting with contest criteria. I can make out only ONE tool (the drill). Rest is junk and parts.', '2009-12-05 12:12:10.000000', NULL, 1),
(5755744, 837122, 112496, '<td valign="top">Not fitting with contest criteria being ''tools'' - not ''girls night out''. Even if you are a tool... you arent literally so doesnt apply.</td>', 'Not fitting with contest criteria being ''tools'' - not ''girls night out''. Even if you are a tool... you arent literally so doesnt apply.', '2009-12-05 12:14:06.000000', NULL, 1),
(5755784, 837148, 5364, '<td valign="top">This is an image that I enjoy, although that''s probably because I like engineering drawings. It''s well lit and you''ve chosen a sensible number of tools. The slide rule is a nice touch.</td>', 'This is an image that I enjoy, although that''s probably because I like engineering drawings. It''s well lit and you''ve chosen a sensible number of tools. The slide rule is a nice touch.', '2009-12-05 13:24:38.000000', NULL, 1),
(5755790, 837043, 5364, '<td valign="top">I like this picture. It''s well lit and a good composition especially the picture of the child implying the reason for using the tools. The one thing you have me confused about is the title - there''s no knitting, so how can there be too much?!</td>', 'I like this picture. It''s well lit and a good composition especially the picture of the child implying the reason for using the tools. The one thing you have me confused about is the title - there''s no knitting, so how can there be too much?!', '2009-12-05 13:29:27.000000', NULL, 1),
(5755800, 835961, 110041, '<td valign="top">Very creepy. The harshness of the flash actually adds to that atmosphere by projecting the shadows.<br/> <br/>The figures are a bit naff. But i like the tools hanging on the left - perhaps a photo of those would be better.</td>', 'Very creepy. The harshness of the flash actually adds to that atmosphere by projecting the shadows. The figures are a bit naff. But i like the tools hanging on the left - perhaps a photo of those would be better.', '2009-12-05 13:37:06.000000', NULL, 1),
(5755805, 837045, 110041, '<td valign="top">I think a deeper depth of field might be better.</td>', 'I think a deeper depth of field might be better.', '2009-12-05 13:45:50.000000', NULL, 1),
(5755806, 836949, 110041, '<td valign="top">it''s a tool of a trade. Perhaps farmers might get a bit more excited about the subject :)</td>', 'it''s a tool of a trade. Perhaps farmers might get a bit more excited about the subject :)', '2009-12-05 13:45:54.000000', NULL, 1),
(5755808, 836938, 110041, '<td valign="top">Good idea.<br/> <br/>I think you''ve got to get tighter in on the darts or get all of the darts in focus.</td>', 'Good idea. I think you''ve got to get tighter in on the darts or get all of the darts in focus.', '2009-12-05 13:49:46.000000', NULL, 1),
(5755850, 836937, 56579, '<td valign="top">The flash makes the light and shadows look very harsh</td>', 'The flash makes the light and shadows look very harsh', '2009-12-05 14:37:40.000000', NULL, 1),
(5756195, 835862, 112618, '<td valign="top">Great theme, smart use of BW, nothing blown out. Stephen King Gunslinger maybe? Great shot man!!</td>', 'Great theme, smart use of BW, nothing blown out. Stephen King Gunslinger maybe? Great shot man!!', '2009-12-05 19:13:49.000000', NULL, 1),
(5756196, 837033, 112618, '<td valign="top">Nice apeture work, whites are bit blown out, but cool concept.</td>', 'Nice apeture work, whites are bit blown out, but cool concept.', '2009-12-05 19:14:38.000000', NULL, 1),
