(5760421, 837000, 23484, '<td valign="top">Ahhh, a five string bass. Neat shot.</td>', 'Ahhh, a five string bass. Neat shot.', '2009-12-08 21:00:53.000000', NULL, 1),
(5760588, 836969, 80859, '<td valign="top">nice composition.  i think the lighting could be better.</td>', 'nice composition.  i think the lighting could be better.', '2009-12-08 23:39:07.000000', NULL, 1),
(5760592, 837020, 61084, '<td valign="top">A great photo. Love the B&amp;W and the canvas texture. Great job. 9</td>', 'A great photo. Love the B&W and the canvas texture. Great job. 9', '2009-12-08 23:41:45.000000', NULL, 1),
(5760593, 837136, 61084, '<td valign="top">I really like the tones in this photo and so far you''re one of the few that actually show the trade effectively. The doll heads are very cool. 8</td>', 'I really like the tones in this photo and so far you''re one of the few that actually show the trade effectively. The doll heads are very cool. 8', '2009-12-08 23:42:13.000000', NULL, 1),
(5760594, 836940, 61084, '<td valign="top">Good clarity and fun, but doesn''t really tell me what trade you''re in or portraying. That could be me on any given Saturday morning. LOL. Like the shot though...good luck!</td>', 'Good clarity and fun, but doesn''t really tell me what trade you''re in or portraying. That could be me on any given Saturday morning. LOL. Like the shot though...good luck!', '2009-12-08 23:43:00.000000', NULL, 1),
(5760600, 835931, 106543, '<td valign="top">I think this is a definite ribbon winner!</td>', 'I think this is a definite ribbon winner!', '2009-12-08 23:47:58.000000', NULL, 1),
(5760608, 835938, 111653, '<td valign="top">nice crisp shot.   simple yet done well...  good composition lighting and coloring!</td>', 'nice crisp shot.   simple yet done well...  good composition lighting and coloring!', '2009-12-08 23:56:46.000000', NULL, 1),
(5760621, 836620, 83313, '<td valign="top">This was my pick for the blue. It still scored pretty darn high. You''re kicking butt and taking names.</td>', 'This was my pick for the blue. It still scored pretty darn high. You''re kicking butt and taking names.', '2009-12-09 00:03:46.000000', NULL, 0),
(5760622, 836178, 73564, '<td valign="top">Love this!! Colors are great! Good job!</td>', 'Love this!! Colors are great! Good job!', '2009-12-09 00:04:00.000000', NULL, 0),
