(5760635, 836620, 60862, '<td valign="top">Fun pic, even better story.  Congrats! :)</td>', 'Fun pic, even better story.  Congrats! :)', '2009-12-09 00:07:29.000000', NULL, 0),
(5760637, 837118, 60571, '<td valign="top">My new PB and a 6+. This was one of the early attempts in the shoot. Several comments were made about too many lines, and I agree completely. In the later shots, the light painting was simplified, but the lighting wasn''t as moody and I loved the mood of the blues and submitted this image instead.</td>', 'My new PB and a 6+. This was one of the early attempts in the shoot. Several comments were made about too many lines, and I agree completely. In the later shots, the light painting was simplified, but the lighting wasn''t as moody and I loved the mood of the blues and submitted this image instead.', '2009-12-09 00:09:41.000000', NULL, 0),
(5760643, 836620, 102534, '<td valign="top">Great pic, fun and lots of energy. I thought this would be looking at a ribbon.</td>', 'Great pic, fun and lots of energy. I thought this would be looking at a ribbon.', '2009-12-09 00:11:10.000000', NULL, 0),
(5760648, 836178, 108580, '<td valign="top">You just have the knack Oliver. Wd again.</td>', 'You just have the knack Oliver. Wd again.', '2009-12-09 00:13:57.000000', NULL, 0),
