(5760653, 836926, 108580, '<td valign="top">WD on a fine and fun shot.</td>', 'WD on a fine and fun shot.', '2009-12-09 00:15:01.000000', NULL, 0),
(5760656, 835931, 108580, '<td valign="top">Great instrument shot. Congrats on HM. I''m learning that it seems DPC''ers prefer the entire animal...</td>', 'Great instrument shot. Congrats on HM. I''m learning that it seems DPC''ers prefer the entire animal...', '2009-12-09 00:16:10.000000', NULL, 0),
(5760658, 837126, 108580, '<td valign="top">Excellent placing, congrats on your HM.</td>', 'Excellent placing, congrats on your HM.', '2009-12-09 00:16:40.000000', NULL, 0),
(5760665, 836620, 108580, '<td valign="top">WD on your high placing. Excellent "gut" shot.</td>', 'WD on your high placing. Excellent "gut" shot.', '2009-12-09 00:18:19.000000', NULL, 0),
(5760667, 835840, 108580, '<td valign="top">WD on top 10!</td>', 'WD on top 10!', '2009-12-09 00:18:51.000000', NULL, 0),
(5760669, 837148, 108580, '<td valign="top">WD on top 10!</td>', 'WD on top 10!', '2009-12-09 00:19:10.000000', NULL, 0),
(5760683, 836752, 108580, '<td valign="top">My only 10. This is a masterful shot with the seal innocently raising it''s head up to ask about the type of lens the photog is using :) The DOF is perfect.<br/>These moments are not contrived and you have to be on the ball to capture them. Excellent expectation and timing Robert. This kind of photography outstrips contrived still life / studio shots as it cannot be (re)created.</td>', 'My only 10. This is a masterful shot with the seal innocently raising it''s head up to ask about the type of lens the photog is using :) The DOF is perfect.These moments are not contrived and you have to be on the ball to capture them. Excellent expectation and timing Robert. This kind of photography outstrips contrived still life / studio shots as it cannot be (re)created.', '2009-12-09 00:23:13.000000', NULL, 0),
(5760684, 837050, 108580, '<td valign="top">WD on top 10!</td>', 'WD on top 10!', '2009-12-09 00:23:33.000000', NULL, 0),
(5760686, 837118, 32011, '<td valign="top">Brilliant photo.  Thought it do much better with the voters, but they''re an unpredicatable bunch.  One of my favourites in the challenge and winner of a MUAIMHO.  Well done... I can''t fault it... can only hope some of those that gave you low scores come and give you some feedback to tell you what they see wrong with this.</td>', 'Brilliant photo.  Thought it do much better with the voters, but they''re an unpredicatable bunch.  One of my favourites in the challenge and winner of a MUAIMHO.  Well done... I can''t fault it... can only hope some of those that gave you low scores come and give you some feedback to tell you what they see wrong with this.', '2009-12-09 00:24:41.000000', NULL, 0),
(5760687, 836178, 98022, '<td valign="top">Great shot! This was my top pick. Congrats on the blue!</td>', 'Great shot! This was my top pick. Congrats on the blue!', '2009-12-09 00:25:03.000000', NULL, 0),
(5760689, 836104, 108580, '<td valign="top">It doesn''t look like you! Next time hire a real thug :)<br/>Excellent placing.</td>', 'It doesn''t look like you! Next time hire a real thug :)Excellent placing.', '2009-12-09 00:25:54.000000', NULL, 0),
(5760692, 836754, 98022, '<td valign="top">Very nice image. I like the DOF and the motion blur of the metronome arm. Congrats on the red!</td>', 'Very nice image. I like the DOF and the motion blur of the metronome arm. Congrats on the red!', '2009-12-09 00:26:23.000000', NULL, 0),
(5760693, 836199, 96751, '<td valign="top">Still love this shot - I suppose I''m one of those that likes dark shots :-)</td>', 'Still love this shot - I suppose I''m one of those that likes dark shots :-)', '2009-12-09 00:26:25.000000', NULL, 0),
(5760707, 836926, 98022, '<td valign="top">Great job. Congrats on the yellow!</td>', 'Great job. Congrats on the yellow!', '2009-12-09 00:29:00.000000', NULL, 0),
(5760710, 837122, 32011, '<td valign="top">Can''t believe this didn''t score much higher.  This is a great image... under appreciated.  Composition is perfect, and I love the fact that you took the challenge differently from most.  Breathe of fresh air when I was voting... very welcomed, I assure you.  A MUAIMHO for your efforts.  Keep up the good work.</td>', 'Can''t believe this didn''t score much higher.  This is a great image... under appreciated.  Composition is perfect, and I love the fact that you took the challenge differently from most.  Breathe of fresh air when I was voting... very welcomed, I assure you.  A MUAIMHO for your efforts.  Keep up the good work.', '2009-12-09 00:29:57.000000', NULL, 0),
(5760715, 836926, 100727, '<td valign="top">There''s nothing wrong with the lines.  It''s a great photo.</td>', 'There''s nothing wrong with the lines.  It''s a great photo.', '2009-12-09 00:31:03.000000', NULL, 0),
(5760716, 835846, 108580, '<td valign="top">Yup, goes to show that on DPC if it isn''t in your face the majority don''t get it and click 1,2,3,4 and move on...don''t be disheartened. This was a fab shot and I gave it an 8. I''m smelling a posthumous...</td>', 'Yup, goes to show that on DPC if it isn''t in your face the majority don''t get it and click 1,2,3,4 and move on...don''t be disheartened. This was a fab shot and I gave it an 8. I''m smelling a posthumous...', '2009-12-09 00:31:31.000000', NULL, 0),
(5760723, 835931, 98022, '<td valign="top">Great shot. Congrats on the HM!</td>', 'Great shot. Congrats on the HM!', '2009-12-09 00:33:11.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5760727, 837126, 98022, '<td valign="top">Awesome reflection. Congrats on the HM!</td>', 'Awesome reflection. Congrats on the HM!', '2009-12-09 00:34:49.000000', NULL, 0),
(5760778, 837050, 3037, '<td valign="top">Thanks for the great comments. It was a while since I posted for a challenge and this is a nice return.</td>', 'Thanks for the great comments. It was a while since I posted for a challenge and this is a nice return.', '2009-12-09 01:00:03.000000', NULL, 0),
(5760859, 835846, 98410, '<td valign="top">I love those shots that I don''t automatically fully understand, but that I want to keep looking at to figure out what''s going on. This is a perfect example!</td>', 'I love those shots that I don''t automatically fully understand, but that I want to keep looking at to figure out what''s going on. This is a perfect example!', '2009-12-09 01:55:13.000000', NULL, 0),
(5760937, 836754, 49109, '<td valign="top">If I had only voted on this challenge  you might have got the blue you deserved. excellent shot lighting-, DOF- and compositionwise. Congrats!</td>', 'If I had only voted on this challenge  you might have got the blue you deserved. excellent shot lighting-, DOF- and compositionwise. Congrats!', '2009-12-09 02:56:48.000000', NULL, 0),
(5760938, 836926, 49109, '<td valign="top">Very nice idea, congrats on the yellow!</td>', 'Very nice idea, congrats on the yellow!', '2009-12-09 02:57:34.000000', NULL, 0),
(5760953, 836178, 52549, '<td valign="top">WTG, Oliver! Super shot, congrats on your blue.</td>', 'WTG, Oliver! Super shot, congrats on your blue.', '2009-12-09 03:33:36.000000', NULL, 0),
(5760961, 837122, 108580, '<td valign="top">I just did a concert shoot 2 weekends ago. Despite my Sigma f/2.8 working flawlessly I am still getting to grips with High ISO and low DOF. This shot, despite the brave "shoehorn" on your part, was a great effort and the BW does help. Keep them coming!</td>', 'I just did a concert shoot 2 weekends ago. Despite my Sigma f/2.8 working flawlessly I am still getting to grips with High ISO and low DOF. This shot, despite the brave "shoehorn" on your part, was a great effort and the BW does help. Keep them coming!', '2009-12-09 03:48:44.000000', NULL, 0),
